from solution import valid_date
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# ---- obviously-correct reference model derived from spec ----
def ref_valid(date):
    if not isinstance(date, str):
        return False
    if len(date) == 0:
        return False
    # format mm-dd-yyyy : exactly 10 chars, '-' at 2 and 5, ascii digits elsewhere
    if len(date) != 10:
        return False
    if date[2] != "-" or date[5] != "-":
        return False
    mm = date[0:2]
    dd = date[3:5]
    yyyy = date[6:10]
    ascii_digits = set("0123456789")
    if not (len(mm) == 2 and len(dd) == 2 and len(yyyy) == 4):
        return False
    if any(c not in ascii_digits for c in mm + dd + yyyy):
        return False
    m = int(mm)
    d = int(dd)
    # year value unconstrained by spec, only format matters
    if m < 1 or m > 12:
        return False
    if m in (1, 3, 5, 7, 8, 10, 12):
        if d < 1 or d > 31:
            return False
    elif m in (4, 6, 9, 11):
        if d < 1 or d > 30:
            return False
    else:  # m == 2
        if d < 1 or d > 29:
            return False
    return True


def max_day(m):
    if m in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if m in (4, 6, 9, 11):
        return 30
    return 29


# ---- concrete examples from spec ----
def test_examples_from_spec():
    assert valid_date('03-11-2000') is True
    assert valid_date('15-01-2012') is False
    assert valid_date('04-0-2040') is False
    assert valid_date('06-04-2020') is True
    assert valid_date('06/04/2020') is False


def test_example_valid_march():
    assert valid_date("03-11-2000") is True


def test_example_invalid_month_15():
    assert valid_date("15-01-2012") is False


def test_example_invalid_day_zero_short():
    # '04-0-2040' is wrong length and day 0
    assert valid_date("04-0-2040") is False


def test_example_valid_june():
    assert valid_date("06-04-2020") is True


def test_example_invalid_slash_separator():
    assert valid_date("06/04/2020") is False


# ---- basic properties ----
def test_empty_string_is_invalid():
    assert valid_date("") is False


def test_none_and_empty_falsy_is_invalid():
    # empty string already covered; None is falsy non-string -> must not be valid
    # spec says empty => False; non-string should never be True
    try:
        r = valid_date(None)
    except Exception:
        # raising is also not True, but spec says return False;
        # we accept exception here to avoid over-constraining, just check not True
        return
    assert r is False


@given(
    m=st.integers(1, 12),
    d=st.integers(1, 29),
    y=st.integers(0, 9999),
)
def test_valid_day_1_to_29_always_accepted(m, d, y):
    s = f"{m:02d}-{d:02d}-{y:04d}"
    assert valid_date(s) is True
    assert ref_valid(s) is True


@given(
    m=st.sampled_from([1, 3, 5, 7, 8, 10, 12]),
    d=st.sampled_from([30, 31]),
    y=st.integers(0, 9999),
)
def test_31day_months_accept_30_31(m, d, y):
    s = f"{m:02d}-{d:02d}-{y:04d}"
    assert valid_date(s) is True


@given(
    m=st.sampled_from([4, 6, 9, 11]),
    y=st.integers(0, 9999),
)
def test_30day_months_accept_day_30(m, y):
    s = f"{m:02d}-30-{y:04d}"
    assert valid_date(s) is True


def test_february_29_accepted():
    assert valid_date("02-29-2000") is True
    assert valid_date("02-29-2020") is True
    assert valid_date("02-29-0000") is True


@given(m=st.integers(0, 99))
def test_invalid_month_number_rejected(m):
    assume(m < 1 or m > 12)
    s = f"{m:02d}-15-2000"
    assert len(s) == 10
    assert valid_date(s) is False
    assert ref_valid(s) is False


@given(
    m=st.sampled_from([1, 3, 5, 7, 8, 10, 12]),
    bad=st.integers(32, 99),
    y=st.integers(0, 9999),
)
def test_31day_months_reject_day_above_31(m, bad, y):
    assume(bad > 31)
    s = f"{m:02d}-{bad:02d}-{y:04d}"
    assert valid_date(s) is False


@given(
    m=st.sampled_from([4, 6, 9, 11]),
    bad=st.sampled_from([31, 32, 33, 45, 99]),
)
def test_30day_months_reject_day_31_and_above(m, bad):
    s = f"{m:02d}-{bad:02d}-2000"
    assert valid_date(s) is False


@given(bad=st.sampled_from([30, 31, 32, 45, 99]))
def test_february_rejects_day_30_and_above(bad):
    s = f"02-{bad:02d}-2000"
    assert valid_date(s) is False


@given(m=st.integers(1, 12))
def test_day_zero_rejected_for_all_months(m):
    s = f"{m:02d}-00-2000"
    assert valid_date(s) is False


@given(m=st.integers(1, 12))
def test_month_zero_rejected(m):
    s = f"00-{15:02d}-2000"
    assert valid_date(s) is False


def test_boundary_days_exhaustive():
    # off-by-one boundaries for each month class
    for m in [1, 3, 5, 7, 8, 10, 12]:
        assert valid_date(f"{m:02d}-01-2000") is True
        assert valid_date(f"{m:02d}-31-2000") is True
        assert valid_date(f"{m:02d}-00-2000") is False
        assert valid_date(f"{m:02d}-32-2000") is False
    for m in [4, 6, 9, 11]:
        assert valid_date(f"{m:02d}-01-2000") is True
        assert valid_date(f"{m:02d}-30-2000") is True
        assert valid_date(f"{m:02d}-31-2000") is False
        assert valid_date(f"{m:02d}-00-2000") is False
    assert valid_date("02-01-2000") is True
    assert valid_date("02-29-2000") is True
    assert valid_date("02-30-2000") is False
    assert valid_date("02-00-2000") is False
    assert valid_date("01-01-2000") is True
    assert valid_date("12-31-2000") is True
    assert valid_date("00-15-2000") is False
    assert valid_date("13-15-2000") is False


def test_month_boundaries():
    assert valid_date("01-15-2000") is True
    assert valid_date("12-15-2000") is True
    assert valid_date("00-15-2000") is False
    assert valid_date("13-15-2000") is False


def test_format_separators_must_be_dashes():
    assert valid_date("06/04/2020") is False
    assert valid_date("06.04.2020") is False
    assert valid_date("06 04 2020") is False
    assert valid_date("06:04:2020") is False
    assert valid_date("03_11_2000") is False
    assert valid_date("03-11/2000") is False
    assert valid_date("03/11-2000") is False


def test_format_length_must_be_10():
    assert valid_date("3-11-2000") is False
    assert valid_date("03-1-2000") is False
    assert valid_date("03-11-200") is False
    assert valid_date("03-11-20000") is False
    assert valid_date("003-11-2000") is False
    assert valid_date("03-011-2000") is False
    assert valid_date("03-11-2000 ") is False
    assert valid_date(" 03-11-2000") is False
    assert valid_date("03-11-2000\n") is False
    assert valid_date("04-0-2040") is False


def test_non_digit_characters_rejected():
    assert valid_date("ab-cd-efgh") is False
    assert valid_date("0a-11-2000") is False
    assert valid_date("03-1a-2000") is False
    assert valid_date("03-11-20a0") is False
    assert valid_date("-- -- ----") is False
    assert valid_date("03-11-2000".replace("0", "o")) is False


def test_unicode_digits_are_not_valid():
    # isdigit() is True for some unicode digits but format requires ascii mm-dd-yyyy
    candidates = ["\u0663", "\u0661", "\u0662", "\u00b2", "\u2160", "\u03b1"]
    for ch in candidates:
        s = f"0{ch}-11-2000"
        # must not return True and must not raise
        try:
            r = valid_date(s)
        except Exception:
            pytest.fail(f"valid_date raised on unicode input {s!r} instead of returning False")
        assert r is False


def test_year_must_be_digits():
    assert valid_date("03-11-abcd") is False
    assert valid_date("03-11-20 0") is False
    assert valid_date("03-11-200*") is False


@given(s=st.text(min_size=0, max_size=12))
def test_equivalence_to_reference_on_arbitrary_text(s):
    assert valid_date(s) == ref_valid(s)


@given(
    s=st.from_regex(r"\d{2}-\d{2}-\d{4}", fullmatch=True),
)
def test_equivalence_to_reference_on_shaped_strings(s):
    assert valid_date(s) == ref_valid(s)


@given(
    m=st.integers(0, 99),
    d=st.integers(0, 99),
    y=st.integers(0, 9999),
)
def test_equivalence_to_reference_on_numeric_grid(m, d, y):
    s = f"{m:02d}-{d:02d}-{y:04d}"
    assert valid_date(s) == ref_valid(s)
